Um ein First-Person-Controller-Skript in GDScript für Godot Engine 3.x zu schreiben und es auf einen KinematicBody-Knoten anzuwenden, folgen Sie diesen Schritten:

1. Erstellen Sie eine neue Scene in Godot und fügen Sie einen KinematicBody-Knoten hinzu.
2. Wählen Sie den KinematicBody-Knoten aus und fügen Sie eine MeshInstance- und eine Camera2D-Komponente hinzu.
3. Ändern Sie die Eigenschaft "Space" der Camera2D-Komponente auf "World".
4. Erstellen Sie eine neue Script-Instanz und wählen Sie sie für den KinematicBody-Knoten aus.
5. Benennen Sie das Skript in "FirstPersonController.gd" um.
6. Fügen Sie folgenden Code in das Skript ein:

```gdscript
extends KinematicBody

export var speed := 10.0
export var mouse_sensitivity := 0.2

var velocity := Vector3.ZERO
var camera := $Camera2D

func _ready():
    Input.set_mouse_mode(Input.MOUSE_MODE_CAPTURED)

func _input(event):
    if event is InputEventMouseMotion:
        var delta := event.relative
        camera.rotate_object_local(Vector3(delta.y, -delta.x, 0), mouse_sensitivity)

func _physics_process(delta):
    velocity = Vector3.ZERO

    if Input.is_action_pressed("move_forward"):
        velocity += -camera.global_transform.basis.z * speed
    if Input.is_action_pressed("move_backward"):
        velocity += camera.global_transform.basis.z * speed
    if Input.is_action_pressed("move_left"):
        velocity += camera.global_transform.basis.x * speed * -1
    if Input.is_action_pressed("move_right"):
        velocity += camera.global_transform.basis.x * speed

    move_and_slide(velocity)
